const modules = [
{title:'Linux & networking foundations',days:'01–07',icon:'>_',tools:'Linux · Bash · DNS',desc:'Understand the machine before automating it.',steps:['Days 1–2: Navigate files, inspect processes, and explain owner/group permissions. Create a practice folder with mkdir -p ~/devops-practice.','Days 3–4: Write a Bash script that reports disk usage and fails on errors using set -eu. Run it twice and compare the output.','Days 5–6: Trace an HTTP request through DNS, TCP, and HTTP. Inspect listening ports with ss -tuln.','Day 7: Diagnose a service on the wrong port. Record symptoms, evidence, fix, and verification.'],cmd:'pwd\nwhoami\nps aux | head\ndf -h\nss -tuln\ncurl -I https://example.com',check:'Explain why a running process can still be unreachable over HTTP.',ref:'https://www.gnu.org/software/bash/manual/bash.html'},
{title:'Git & collaborative delivery',days:'08–13',icon:'⑂',tools:'Git · GitHub · Pull requests',desc:'Turn changes into a reviewable history.',steps:['Days 8–9: Create a separate practice repository, add a README, and make a first commit.','Days 10–11: Create a feature branch, change a file, inspect git diff, and open a pull request on GitHub.','Days 12–13: Intentionally create and resolve a merge conflict. Use git revert to undo a committed change while preserving history.'],cmd:'mkdir -p ~/devops-practice/git-lab\ncd ~/devops-practice/git-lab\ngit init\ngit switch -c learning\ngit status',check:'Show a reviewed change and explain merge versus revert.',ref:'https://git-scm.com/book/en/v2'},
{title:'Containers & local environments',days:'14–21',icon:'▱',tools:'Docker · Compose · Images',desc:'Package a service and make it reproducible.',steps:['Days 14–15: Install Docker using its official instructions, then run the welcome container below.','Days 16–17: Create a Dockerfile for a small app. Compare image layers and container writable storage.','Days 18–19: Follow the Docker application-stack tutorial. Identify the frontend, API, database, and proxy.','Days 20–21: Break a port mapping, inspect docker logs, repair it, and document the difference between host and container ports.'],cmd:'docker version\ndocker run --detach --name flightpath-welcome --publish 127.0.0.1:8081:80 docker/welcome-to-docker\ncurl -I http://localhost:8081\ndocker logs flightpath-welcome\n# Cleanup only this practice container:\ndocker rm -f flightpath-welcome',check:'Recreate a container and explain which data persists and why.',ref:'https://docs.docker.com/get-started/tutorials/run-an-app/'},
{title:'Continuous integration & security',days:'22–29',icon:'⇄',tools:'GitHub Actions · Trivy · Registry',desc:'Make every change earn its way to release.',steps:['Days 22–23: Read the Actions guide and create a workflow triggered by pull_request. Give the workflow contents: read permissions.','Days 24–25: Add test and container-build jobs. Use needs so build follows successful tests. Make a test fail and confirm later jobs stop.','Days 26–27: Add a Trivy image scan. Define a severity policy and review findings rather than silently ignoring them.','Days 28–29: On trusted main-branch pushes only, authenticate to GHCR with a scoped token, publish an image tagged by commit SHA, and record its digest. Never expose publishing credentials to untrusted pull requests.'],cmd:'# Local build example, after creating your Dockerfile:\ndocker build -t learning-app:local .\n# With Trivy installed:\ntrivy image --severity HIGH,CRITICAL --exit-code 1 learning-app:local',check:'Demonstrate that a failing test blocks image publication.',ref:'https://docs.github.com/en/actions/get-started/understand-github-actions'},
{title:'Infrastructure as code',days:'30–36',icon:'◇',tools:'Terraform · State · Plans',desc:'Describe infrastructure, then review the change.',steps:['Days 30–31: Install Terraform and follow the official Docker-based tutorial to avoid cloud charges.','Days 32–33: Explain providers, resources, variables, and outputs. Format and validate your configuration.','Days 34–35: Review terraform plan before apply. Change a variable and explain the resulting diff. Protect state because it may contain sensitive data.','Day 36: Run terraform destroy only in your isolated tutorial directory after reviewing the plan; verify the tutorial resources are gone.'],cmd:'# In the official tutorial configuration directory:\nterraform init\nterraform fmt -check\nterraform validate\nterraform plan\n# Review the plan before running terraform apply.',check:'Explain desired state, drift, and why state must not be committed to Git.',ref:'https://developer.hashicorp.com/terraform/tutorials'},
{title:'Kubernetes & GitOps delivery',days:'37–46',icon:'⎈',tools:'Kubernetes · Argo CD · Helm',desc:'Deploy, reconcile, and recover your application.',steps:['Days 37–39: Install a local Kubernetes cluster using the official Basics tutorial. Create a Deployment and ClusterIP Service.','Days 40–41: Add readiness/liveness probes, resource requests, and limits. Use port-forward to reach your service locally.','Days 42–43: Roll out a new image, inspect rollout status, and practice undoing a bad deployment.','Days 44–46: Install Argo CD in the local cluster using its quick start. Point an Application at your own Git manifests. Change an image digest in Git and observe reconciliation. Review Helm templates before applying them.'],cmd:'kubectl get nodes\nkubectl get deployments,services,pods\n# Replace learning-app with your Deployment name:\nkubectl rollout status deployment/learning-app\nkubectl logs deployment/learning-app\nkubectl port-forward service/learning-app 8082:80',check:'Delete a practice Pod, observe recovery, and explain why GitOps restores desired state.',ref:'https://kubernetes.io/docs/tutorials/kubernetes-basics/'},
{title:'Observability & reliable operations',days:'47–54',icon:'⌁',tools:'Prometheus · Grafana · Alertmanager',desc:'Know what your service is doing and when it hurts.',steps:['Days 47–48: Expose an application metrics endpoint and configure a Prometheus scrape target. Verify the target is up.','Days 49–50: Query request rate, error rate, and latency. Build a Grafana dashboard from Prometheus.','Days 51–52: Define a learning SLO such as 99% successful requests. Create an alert for a sustained error rate and route it through Alertmanager.','Days 53–54: Inject an error into your local app, confirm detection, recover, and write a short incident review. Keep metrics, logs, and traces conceptually distinct.'],cmd:'# In the Prometheus query UI:\nup\n# Example only: instrument this counter in your app first.\nrate(http_requests_total[5m])',check:'Demonstrate an alert firing and resolving, with a timeline of the incident.',ref:'https://prometheus.io/docs/introduction/overview/'},
{title:'Capstone: ship with confidence',days:'55–60',icon:'↗',tools:'Release · Recovery · Documentation',desc:'Connect the whole system into one delivery story.',steps:['Day 55: Draw your actual architecture and label trust boundaries, request paths, and delivery paths.','Day 56: Open a feature pull request, run tests and scans, merge it, and publish an immutable image.','Day 57: Update the GitOps repository with the new image digest. Observe Argo CD sync and verify the service.','Day 58: Simulate a failed release in the local environment and revert the manifest commit to restore a known good image.','Days 59–60: Capture dashboard evidence, write a runbook, document setup and cleanup, and present your change from commit to customer.'],cmd:'# Record evidence for your portfolio:\ngit log --oneline -5\nkubectl get deployments,pods,services\nkubectl rollout status deployment/learning-app',check:'A peer can reproduce the project from your README and recover from a failed release.',ref:'https://argo-cd.readthedocs.io/en/stable/'}
];
const resources=[['Docker','Build and share a containerized application.',modules[2].ref],['GitHub Actions','Workflows, events, jobs, runners, and delivery.',modules[3].ref],['Kubernetes','Deploy, expose, scale, and update an application.',modules[5].ref],['Terraform','Learn providers, plans, state, and infrastructure.',modules[4].ref],['Argo CD','Understand declarative GitOps and reconciliation.',modules[7].ref],['Prometheus','Metrics collection, queries, and alerting.',modules[6].ref],['Git','The free Pro Git book, from basics to branching.',modules[1].ref],['Bash','The official shell reference for deeper learning.',modules[0].ref],['Trivy','Container scanning and vulnerability policies.','https://trivy.dev/latest/docs/'],['Grafana','Build dashboards and explore telemetry.','https://grafana.com/docs/grafana/latest/']];
let done=[];try{done=JSON.parse(localStorage.getItem('flightpath-progress')||'[]');if(!Array.isArray(done))done=[];done=done.filter(i=>Number.isInteger(i)&&i>=0&&i<8)}catch{}let current=0,running=false;
const $=s=>document.querySelector(s),esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
function title(t,s){return `<div class="intro"><div><h1>${t}</h1><p>${s}</p></div><span class="pill">◷ &nbsp; 60-day guided journey</span></div>`}
function card(m,i){return `<button class="track-card" data-lesson="${i}"><span class="icon">${m.icon}</span><div><h3>${m.title}</h3><p>Days ${m.days} &nbsp; · &nbsp; ${m.tools}</p></div><span class="num">${done.includes(i)?'✓ Done':'↗'}</span></button>`}
function map(compact=false){return `<div class="map"><div class="mini-label">${compact?'FROM COMMIT TO CUSTOMER':'DELIVERY PLANE · CLICK A SERVICE TO EXPLORE'}</div><div class="map-row"><button class="node" data-lesson="1"><b>⑂ GitHub</b><small>Source & review</small></button><span class="arrow">→</span><button class="node" data-lesson="3"><b>⇄ Actions + Trivy</b><small>Test · build · scan</small></button><span class="arrow">→</span><button class="node" data-lesson="3"><b>▱ GHCR</b><small>Immutable images</small></button></div><div class="map-caption">CI updates the image digest in the GitOps repository ↓</div><div class="map-row"><button class="node" data-lesson="1"><b>⑂ GitOps repository</b><small>Desired state</small></button><span class="arrow">→</span><button class="node" data-lesson="5"><b>↻ Argo CD</b><small>Reconciliation</small></button><span class="arrow">→</span><button class="node" data-lesson="5"><b>⎈ Kubernetes</b><small>Application workloads</small></button></div>${compact?'':`<div class="map-caption">RUNTIME PLANE · HTTP REQUEST FLOW</div><div class="map-row"><span class="node"><b>Browser</b><small>HTTP client</small></span><span class="arrow">→</span><button class="node" data-lesson="5"><b>Ingress / Service</b><small>Route traffic</small></button><span class="arrow">→</span><button class="node" data-lesson="2"><b>Frontend → API</b><small>Application Pods</small></button><span class="arrow">→</span><button class="node" data-lesson="2"><b>PostgreSQL</b><small>Persistent data</small></button></div><div class="map-caption">SUPPORTING SERVICES</div><div class="map-row"><button class="node" data-lesson="4"><b>◇ Terraform</b><small>Provision infrastructure</small></button><button class="node" data-lesson="6"><b>Prometheus</b><small>Scrape app metrics</small></button><span class="arrow">→</span><button class="node" data-lesson="6"><b>Grafana / Alertmanager</b><small>Dashboards & alerts</small></button></div>`}<p class="map-caption">Reference architecture · services are learning targets, not running resources</p></div>`}
function render(){const route=location.hash.slice(1)||'overview';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${route}`));$('#breadcrumb').textContent=({overview:'Overview',roadmap:'Learning path',architecture:'Architecture',pipeline:'Pipeline lab',resources:'Resource library',setup:'Run locally'})[route]||'Overview';const next=modules.findIndex((_,i)=>!done.includes(i));let html='';
if(route==='overview')html=title('Your next chapter starts here.','Go from learning the tools to connecting the whole system.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">THE DEVOPS LEARNING PATH</div><h2>Small steps.<br><em>Production-sized thinking.</em></h2><p>Build a complete delivery pipeline, understand every service, and learn what happens between commit and customer.</p><button class="btn primary" data-lesson="${next<0?0:next}">${done.length?'Continue learning':'Start your journey'} <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="orb">⑂</span><span class="orb">⎈</span><span class="orb">▱</span><span class="orb center">↗</span></div></div></section><div class="stats"><div class="stat"><label>Your progress</label><strong>${Math.round(done.length/8*100)}%</strong><small>${done.length} of 8 modules</small><div class="bar"><i style="width:${done.length/8*100}%"></i></div></div><div class="stat"><label>Learning roadmap</label><strong>60</strong><small>days, at your pace</small></div><div class="stat"><label>Connected disciplines</label><strong>08</strong><small>hands-on modules</small></div><div class="stat"><label>Your destination</label><strong>01</strong><small>end-to-end capstone</small></div></div><div class="two-col"><section><div class="section-head"><h2>Make your next move</h2><a class="text-link" href="#roadmap">View full path ↗</a></div>${modules.slice(0,3).map(card).join('')}</section><section><div class="section-head"><h2>The bigger picture</h2><span class="tag">SYSTEM THINKING</span></div><div class="card"><div class="eyebrow" style="color:var(--teal)">CODE → CLOUD → CONFIDENCE</div><h3>Every tool has a purpose.</h3><p>Follow a change through review, testing, image delivery, deployment, and monitoring.</p><a href="#architecture" class="btn">Explore architecture <span>↗</span></a></div></section></div>`;
else if(route==='roadmap')html=title('One path. Eight milestones.','Spend 45–90 minutes a day. Complete each lab before marking it done.')+`<div class="callout">Your progress stays in this browser. Modules are self-paced; the day ranges are a suggested schedule.</div>${modules.map(card).join('')}<button class="btn" id="reset">Reset learning progress</button>`;
else if(route==='architecture')html=title('See how everything connects.','A reference architecture for your end-to-end capstone.')+map()+`<div class="callout">Start locally with Docker and a local Kubernetes cluster. This map illustrates a target system; Flightpath itself is a static learning app. Terraform provisions infrastructure, Argo CD reconciles manifests, and Kubernetes runs workloads. Application data needs its own storage and backup plan.</div><div class="grid"><div class="card"><h3>01 / Delivery</h3><p>A commit passes tests and scans. CI publishes an image and proposes a manifest update. GitOps pulls approved desired state.</p></div><div class="card"><h3>02 / Runtime</h3><p>Ingress routes requests to Services and Pods. The API accesses PostgreSQL. Probes and limits help keep workloads healthy.</p></div><div class="card"><h3>03 / Feedback</h3><p>Prometheus scrapes metrics. Grafana visualizes them. Alertmanager routes actionable alerts back to the operator.</p></div></div>`;
else if(route==='pipeline')html=title('Watch a change take flight.','Explore stage ordering and failure gates before wiring up real CI/CD.')+`<div class="callout">Interactive simulation only. No commands run, images publish, or cloud resources deploy.</div><label for="scenario">Practice scenario &nbsp;</label><select id="scenario"><option value="success">Successful release</option><option value="test">Fail a test</option><option value="scan">Block a vulnerable image</option></select><button class="btn teal" id="run">▶ Run simulation</button><div class="pipeline">${['Commit','Test','Build','Scan','Publish','Deploy'].map((s,i)=>`<div class="stage" id="stage-${i}"><span>0${i+1}</span><b>${s}</b><small>Waiting</small></div>`).join('')}</div><pre class="log" id="log" aria-live="polite">$ flightpath simulate\nReady. Choose a scenario and run the pipeline.</pre><div class="card"><h3>What happens after a failure?</h3><p>Downstream stages stop. Fix the failed gate, commit the change, and rerun. In a real GitOps flow, deployment follows an approved manifest change and reconciliation—not merely a successful image build.</p></div>`;
else if(route==='resources')html=title('Go straight to the source.','Official documentation, connected to what you are learning.')+`<input class="search" id="search" aria-label="Search resources" placeholder="Search tools, concepts, or documentation…"><div class="grid" id="resource-grid">${resourceCards(resources)}</div><p>Core references checked online on 5 November 2026. Documentation may evolve; follow current installation instructions from each project.</p>`;
else if(route==='setup')html=title('Your lab, on your machine.','No package installation needed to run the learning dashboard.')+`<div class="two-col"><div><div class="card"><span class="tag">OPTION 01 · PYTHON 3</span><h3>Start the dashboard</h3><p>Open a terminal and run these commands. Keep the terminal open while learning.</p><pre id="setup-code">cd /home/btcchl002/devops-60-days/flightpath\npython3 -m http.server 8080 --bind 127.0.0.1 --directory dist</pre><button class="btn" id="copy">Copy commands</button><p>Open <a class="text-link" href="http://localhost:8080" target="_blank" rel="noopener">http://localhost:8080 ↗</a>. Press Ctrl+C in the terminal to stop. If port 8080 is occupied, use 8083 instead.</p></div></div><div class="card"><span class="tag">WHEN YOU REACH THE LAB</span><h3>Install tools incrementally</h3><p>Start with Bash, Git, and Python 3. Add Docker in module 3, Terraform in module 5, then kubectl and a local cluster in module 6.</p><p>The dashboard saves progress locally in your browser. It does not require credentials or a cloud account. The curriculum includes external tools and services you install separately.</p><a class="text-link" href="#resources">Open official installation references ↗</a></div></div>`;
else{location.hash='overview';return}$('#content').innerHTML=html;document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(Number(b.dataset.lesson)));if($('#search'))$('#search').oninput=e=>{$('#resource-grid').innerHTML=resourceCards(resources.filter(r=>r.join(' ').toLowerCase().includes(e.target.value.toLowerCase())))};if($('#run'))$('#run').onclick=simulate;if($('#reset'))$('#reset').onclick=()=>{if(confirm('Reset all completed modules in this browser?')){done=[];save();render()}};if($('#copy'))$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#setup-code').textContent);toast('Commands copied')}catch{toast('Select and copy the commands above')}}}
function resourceCards(list){return list.length?list.map(r=>`<a class="card resource" href="${r[2]}" target="_blank" rel="noopener noreferrer"><span>OFFICIAL DOCUMENTATION ↗</span><h3>${r[0]}</h3><p>${r[1]}</p></a>`).join(''):'<div class="empty">No resources found. Try “Docker” or “metrics”.</div>'}
function save(){try{localStorage.setItem('flightpath-progress',JSON.stringify(done))}catch{toast('Browser storage unavailable; progress lasts for this session')}}
function openLesson(i){current=i;const m=modules[i];$('#lesson-body').innerHTML=`<div class="eyebrow" style="color:var(--teal)">MODULE ${String(i+1).padStart(2,'0')} · DAYS ${m.days}</div><h2 style="margin-top:20px">${m.title}</h2><p>${m.desc}</p><span class="tag">${m.tools}</span><ol class="lesson-list">${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h3>Try it yourself</h3><pre>${esc(m.cmd)}</pre><div class="callout"><b>Checkpoint</b><br>${m.check}</div><p><a class="text-link" target="_blank" rel="noopener noreferrer" href="${m.ref}">Read the official guide ↗</a></p><button class="btn teal" id="complete">${done.includes(i)?'Mark as incomplete':'Mark module complete'}</button>`;$('#complete').onclick=()=>{done=done.includes(current)?done.filter(x=>x!==current):[...done,current];save();$('#lesson').close();render();toast('Learning progress updated')};$('#lesson').showModal()}
$('.close').onclick=()=>$('#lesson').close();$('#lesson').onclick=e=>{if(e.target===$('#lesson'))$('#lesson').close()};function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
async function simulate(){if(running)return;running=true;const run=$('#run'),scenario=$('#scenario').value,log=$('#log'),stages=[...document.querySelectorAll('.stage')];run.disabled=true;$('#scenario').disabled=true;stages.forEach(s=>{s.className='stage';s.style.borderColor='';s.querySelector('small').textContent='Waiting'});log.textContent='$ flightpath simulate --scenario '+scenario+'\n';const messages=['Source revision received.','Unit and integration checks passed.','Container image built.','Security policy passed.','Immutable image published to practice registry.','GitOps manifest reconciled; health checks passed.'];for(let i=0;i<6;i++){stages[i].classList.add('running');stages[i].querySelector('small').textContent='Running…';await new Promise(r=>setTimeout(r,650));if((scenario==='test'&&i===1)||(scenario==='scan'&&i===3)){stages[i].classList.remove('running');stages[i].style.borderColor='#c56060';stages[i].querySelector('small').textContent='Failed';log.textContent+=`✕ ${i===1?'Assertion failed: expected HTTP 200, received 500.':'Critical vulnerability exceeds the scan policy.'}\nPipeline blocked. Fix the issue before publishing.\n`;for(let j=i+1;j<6;j++)stages[j].querySelector('small').textContent='Skipped';break}stages[i].style.borderColor='';stages[i].classList.remove('running');stages[i].classList.add('passed');stages[i].querySelector('small').textContent='Passed';log.textContent+='✓ '+messages[i]+'\n'}running=false;run.disabled=false;if($('#scenario'))$('#scenario').disabled=false}
window.addEventListener('hashchange',render);render();
